package com.johnny.hotel.inspection;import com.johnny.hotel.common.Result;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/housekeeping/inspections") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('STAFF','MANAGER','OWNER','SUPER_ADMIN')") public class InspectionController{private final InspectionService service;@GetMapping("/{id}")public Result<RoomInspection> get(@PathVariable Long id){return Result.success(service.get(id));}@GetMapping public Result<List<RoomInspection>> room(@RequestParam Long roomId){return Result.success(service.room(roomId));}@PostMapping("/{id}/decision")public Result<RoomInspection> decide(@PathVariable Long id,@Valid @RequestBody InspectionRequests.Decide r){return Result.success(service.decide(id,r));}}
